package ae.bitemporal;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class TimelineTest {

    private static Segment<String> seg(long from, long to, String v) {
        return new Segment<>(from, to, v);
    }

    @Test
    void emptyTimelineHasNoValues() {
        Timeline<String> t = Timeline.empty();
        assertTrue(t.segments().isEmpty());
        assertEquals(Optional.empty(), t.valueAt(0));
    }

    @Test
    void assignInEmptyThenReadHalfOpen() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 10, "A");
        assertEquals(Optional.of("A"), t.valueAt(0));
        assertEquals(Optional.of("A"), t.valueAt(9));
        assertEquals(Optional.empty(), t.valueAt(10));
        assertEquals(Optional.empty(), t.valueAt(-1));
    }

    @Test
    void assignInsideSplitsTheSurroundingSegment() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 10, "A").assign(3, 6, "B");
        assertEquals(List.of(seg(0, 3, "A"), seg(3, 6, "B"), seg(6, 10, "A")), t.segments());
    }

    @Test
    void assignOverlappingTwoSegmentsTrimsBoth() {
        Timeline<String> t = Timeline.<String>empty()
                .assign(0, 4, "A").assign(6, 10, "B").assign(2, 8, "C");
        assertEquals(List.of(seg(0, 2, "A"), seg(2, 8, "C"), seg(8, 10, "B")), t.segments());
    }

    @Test
    void adjacentEqualValuesCoalesce() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 5, "A").assign(5, 10, "A");
        assertEquals(List.of(seg(0, 10, "A")), t.segments());
    }

    @Test
    void adjacentDifferentValuesStaySeparate() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 5, "A").assign(5, 10, "B");
        assertEquals(List.of(seg(0, 5, "A"), seg(5, 10, "B")), t.segments());
    }

    @Test
    void assigningTheSameValueInsideChangesNothing() {
        Timeline<String> a = Timeline.<String>empty().assign(0, 10, "A");
        assertEquals(a, a.assign(2, 4, "A"));
    }

    @Test
    void healingAGapCoalescesThreeSegmentsIntoOne() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 10, "A").clear(4, 6).assign(4, 6, "A");
        assertEquals(List.of(seg(0, 10, "A")), t.segments());
    }

    @Test
    void clearMiddleLeavesTwoPieces() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 10, "A").clear(4, 6);
        assertEquals(List.of(seg(0, 4, "A"), seg(6, 10, "A")), t.segments());
    }

    @Test
    void clearEdgesAndWholeSegment() {
        Timeline<String> base = Timeline.<String>empty().assign(0, 10, "A");
        assertEquals(List.of(seg(3, 10, "A")), base.clear(-5, 3).segments());
        assertEquals(List.of(seg(0, 7, "A")), base.clear(7, 20).segments());
        assertTrue(base.clear(0, 10).segments().isEmpty());
        assertTrue(base.clear(-100, 100).segments().isEmpty());
    }

    @Test
    void clearOutsideAnythingReturnsEqualTimeline() {
        Timeline<String> base = Timeline.<String>empty().assign(5, 10, "A");
        assertEquals(base, base.clear(0, 5));
        assertEquals(base, base.clear(10, 20));
    }

    @Test
    void foreverIsAnOrdinaryUpperBound() {
        Timeline<String> t = Timeline.<String>empty().assign(5, Segment.FOREVER, "X");
        assertEquals(Optional.of("X"), t.valueAt(Long.MAX_VALUE - 1));
        assertEquals(Optional.empty(), t.valueAt(Long.MAX_VALUE));
        assertEquals(List.of(seg(5, 100, "X")), t.clear(100, Segment.FOREVER).segments());
    }

    @Test
    void negativeValidTimesWork() {
        Timeline<String> t = Timeline.<String>empty().assign(Long.MIN_VALUE, 0, "OLD");
        assertEquals(Optional.of("OLD"), t.valueAt(Long.MIN_VALUE));
        assertEquals(Optional.empty(), t.valueAt(0));
    }

    @Test
    void segmentsViewIsUnmodifiable() {
        Timeline<String> t = Timeline.<String>empty().assign(0, 1, "A");
        assertThrows(UnsupportedOperationException.class, () -> t.segments().clear());
    }

    @Test
    void invalidArgumentsAreRejected() {
        Timeline<String> t = Timeline.empty();
        assertThrows(IllegalArgumentException.class, () -> t.assign(5, 5, "A"));
        assertThrows(IllegalArgumentException.class, () -> t.assign(6, 5, "A"));
        assertThrows(IllegalArgumentException.class, () -> t.assign(0, 5, null));
        assertThrows(IllegalArgumentException.class, () -> t.clear(5, 5));
        assertThrows(IllegalArgumentException.class, () -> new Segment<>(3, 3, "A"));
        assertThrows(IllegalArgumentException.class, () -> new Segment<>(0, 1, null));
    }
}

package ae.bitemporal;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Random;
import org.junit.jupiter.api.Test;

/** Differential test: the store against a brute-force array-per-transaction oracle. */
class RandomizedOracleTest {

    /** Valid times 0..N-1 are real cells; cell N stands for the whole range [N, FOREVER). */
    private static final int N = 24;
    private static final String[] KEYS = {"k0", "k1", "k2"};
    private static final String[] VALUES = {"A", "B", "C"};

    /** oracle state: [key][cell] -> value or null. */
    private static String[][] copy(String[][] s) {
        String[][] c = new String[s.length][];
        for (int i = 0; i < s.length; i++) {
            c[i] = s[i].clone();
        }
        return c;
    }

    private static void oracleAssert(String[][] s, int k, long from, long to, String v) {
        for (int c = (int) from; c <= (to == Segment.FOREVER ? N : to - 1); c++) {
            s[k][c] = v;
        }
    }

    /** Runs of equal non-null cells, translated to segments (last cell N means FOREVER). */
    private static List<Segment<String>> oracleSegments(String[] cells) {
        List<Segment<String>> out = new ArrayList<>();
        int c = 0;
        while (c <= N) {
            if (cells[c] == null) {
                c++;
                continue;
            }
            int e = c;
            while (e + 1 <= N && cells[c].equals(cells[e + 1])) {
                e++;
            }
            out.add(new Segment<>(c, e == N ? Segment.FOREVER : e + 1, cells[c]));
            c = e + 1;
        }
        return out;
    }

    private static List<Delta<String>> oracleDiff(String[] a, String[] b) {
        List<Delta<String>> out = new ArrayList<>();
        int c = 0;
        while (c <= N) {
            if (java.util.Objects.equals(a[c], b[c])) {
                c++;
                continue;
            }
            int e = c;
            while (e + 1 <= N && java.util.Objects.equals(a[e + 1], a[c])
                    && java.util.Objects.equals(b[e + 1], b[c])) {
                e++;
            }
            out.add(new Delta<>(c, e == N ? Segment.FOREVER : e + 1, a[c], b[c]));
            c = e + 1;
        }
        return out;
    }

    private static void checkInvariants(List<Segment<String>> segs) {
        for (int i = 0; i < segs.size(); i++) {
            Segment<String> s = segs.get(i);
            assertTrue(s.from() < s.to(), "empty segment in " + segs);
            if (i > 0) {
                Segment<String> p = segs.get(i - 1);
                assertTrue(p.to() <= s.from(), "overlap/unsorted in " + segs);
                if (p.to() == s.from()) {
                    assertNotEquals(p.value(), s.value(), "uncoalesced in " + segs);
                }
            }
        }
    }

    @Test
    void storeAgreesWithOracleAcrossSeededRuns() {
        int totalTx = 0;
        int noOps = 0;
        for (long seed = 1; seed <= 60; seed++) {
            Random rnd = new Random(seed);
            long[] clock = {0};
            BitemporalStore<String, String> store = new BitemporalStore<>(() -> clock[0]);
            List<String[][]> states = new ArrayList<>();
            List<Long> stamps = new ArrayList<>();
            states.add(new String[KEYS.length][N + 1]);
            stamps.add(-1L);
            String[][] live = states.get(0);

            for (int step = 0; step < 40; step++) {
                clock[0] += rnd.nextInt(3);
                String[][] next = copy(live);
                int ops = 1 + rnd.nextInt(3);
                long before = store.currentTx();
                long tx = store.transact(t -> {
                    for (int o = 0; o < ops; o++) {
                        int k = rnd.nextInt(KEYS.length);
                        long from = rnd.nextInt(N);
                        long to = rnd.nextInt(6) == 0 ? Segment.FOREVER : from + 1 + rnd.nextInt(N - (int) from);
                        if (rnd.nextInt(4) == 0) {
                            t.retract(KEYS[k], from, to);
                            oracleAssert(next, k, from, to, null);
                        } else {
                            String v = VALUES[rnd.nextInt(VALUES.length)];
                            t.assertValue(KEYS[k], from, to, v);
                            oracleAssert(next, k, from, to, v);
                        }
                    }
                });
                boolean changed = !java.util.Arrays.deepEquals(live, next);
                if (changed) {
                    assertEquals(before + 1, tx, "seed " + seed + " step " + step);
                    states.add(next);
                    stamps.add(clock[0]);
                    live = next;
                    totalTx++;
                } else {
                    assertEquals(before, tx, "no-op must not be recorded, seed " + seed);
                    noOps++;
                }
                assertEquals(states.size() - 1, store.currentTx());
                for (String key : KEYS) {
                    checkInvariants(store.history(key));
                }
            }

            // every tx, key and valid time
            for (int tx = 0; tx < states.size(); tx++) {
                for (int k = 0; k < KEYS.length; k++) {
                    assertEquals(oracleSegments(states.get(tx)[k]), store.history(KEYS[k], tx),
                            "history seed " + seed + " tx " + tx + " key " + k);
                    for (int c = 0; c <= N; c++) {
                        long t = c;
                        assertEquals(Optional.ofNullable(states.get(tx)[k][c]),
                                store.valueAt(KEYS[k], t, tx));
                    }
                }
                final int fTx = tx;
                for (int c = 0; c <= N; c += 5) {
                    var snap = store.snapshot(c, fTx);
                    for (int k = 0; k < KEYS.length; k++) {
                        String want = states.get(fTx)[k][c];
                        assertEquals(want, snap.get(KEYS[k]), "snapshot seed " + seed);
                    }
                }
            }

            // diffs for random tx pairs
            for (int i = 0; i < 15; i++) {
                int a = rnd.nextInt(states.size());
                int b = rnd.nextInt(states.size());
                int k = rnd.nextInt(KEYS.length);
                assertEquals(oracleDiff(states.get(a)[k], states.get(b)[k]), store.diff(KEYS[k], a, b),
                        "diff seed " + seed + " " + a + "->" + b);
            }

            // revisions for random instants
            for (int i = 0; i < 10; i++) {
                int k = rnd.nextInt(KEYS.length);
                int c = rnd.nextInt(N + 1);
                List<Revision<String>> want = new ArrayList<>();
                String last = null;
                for (int tx = 1; tx < states.size(); tx++) {
                    String v = states.get(tx)[k][c];
                    if (v != null && !v.equals(last) || v == null && last != null) {
                        want.add(new Revision<>(tx, stamps.get(tx), v));
                    }
                    last = v;
                }
                assertEquals(want, store.revisions(KEYS[k], c), "revisions seed " + seed);
            }

            // txAtTime against the stamps
            for (long ts = 0; ts <= clock[0] + 1; ts++) {
                int want = 0;
                for (int tx = 1; tx < states.size(); tx++) {
                    if (stamps.get(tx) <= ts) {
                        want = tx;
                    }
                }
                assertEquals(want, store.txAtTime(ts), "txAtTime seed " + seed + " ts " + ts);
            }
        }
        // The generator must exercise both branches, otherwise the test proves little.
        assertTrue(totalTx > 1000, "too few recorded transactions: " + totalTx);
        assertTrue(noOps > 20, "too few no-op transactions: " + noOps);
    }

    @Test
    void failedRandomTransactionsLeaveNoTrace() {
        Random rnd = new Random(99);
        long[] clock = {0};
        BitemporalStore<String, String> store = new BitemporalStore<>(() -> clock[0]);
        store.assertValue("k0", 0, 10, "A");
        List<Segment<String>> before = store.history("k0");
        for (int i = 0; i < 50; i++) {
            int failAt = rnd.nextInt(3);
            assertThrows(IllegalArgumentException.class, () -> store.transact(t -> {
                for (int o = 0; o < 3; o++) {
                    if (o == failAt) {
                        t.assertValue("k0", 5, 5, "Z");
                    }
                    t.assertValue("k" + o, 0, 20, "Z");
                }
            }));
        }
        assertEquals(1, store.currentTx());
        assertEquals(before, store.history("k0"));
        assertTrue(store.history("k1").isEmpty());
    }
}

package ae.bitemporal;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class BitemporalStoreTest {

    private long now;
    private BitemporalStore<String, String> store;

    @BeforeEach
    void setUp() {
        now = 100;
        store = new BitemporalStore<>(() -> now);
    }

    private static Segment<String> seg(long from, long to, String v) {
        return new Segment<>(from, to, v);
    }

    @Test
    void newStoreIsEmptyAtTxZero() {
        assertEquals(0, store.currentTx());
        assertEquals(Optional.empty(), store.valueAt("p", 5));
        assertTrue(store.history("p").isEmpty());
        assertTrue(store.snapshot(5, 0).isEmpty());
    }

    @Test
    void assertReturnsIncreasingTxIds() {
        assertEquals(1, store.assertValue("p", 0, 10, "A"));
        assertEquals(2, store.assertValue("p", 3, 6, "B"));
        assertEquals(2, store.currentTx());
    }

    @Test
    void overwriteSplitsAndOldKnowledgeSurvives() {
        store.assertValue("p", 0, 10, "A");
        store.assertValue("p", 3, 6, "B");
        assertEquals(List.of(seg(0, 3, "A"), seg(3, 6, "B"), seg(6, 10, "A")), store.history("p"));
        assertEquals(List.of(seg(0, 10, "A")), store.history("p", 1));
        assertEquals(Optional.of("B"), store.valueAt("p", 4, 2));
        assertEquals(Optional.of("A"), store.valueAt("p", 4, 1));
        assertEquals(Optional.empty(), store.valueAt("p", 4, 0));
    }

    @Test
    void retractRemovesOnlyTheGivenRange() {
        store.assertValue("p", 0, 10, "A");
        assertEquals(2, store.retract("p", 4, 6));
        assertEquals(List.of(seg(0, 4, "A"), seg(6, 10, "A")), store.history("p"));
        assertEquals(Optional.empty(), store.valueAt("p", 5));
        assertEquals(Optional.of("A"), store.valueAt("p", 5, 1));
    }

    @Test
    void foreverIntervalsAreSupported() {
        store.assertValue("p", 5, Segment.FOREVER, "X");
        store.retract("p", 100, Segment.FOREVER);
        assertEquals(List.of(seg(5, 100, "X")), store.history("p"));
        assertEquals(Optional.of("X"), store.valueAt("p", 1_000_000, 1));
    }

    @Test
    void noOpAssertIsNotRecorded() {
        store.assertValue("p", 0, 10, "A");
        assertEquals(1, store.assertValue("p", 2, 4, "A"));
        assertEquals(1, store.retract("p", 20, 30));
        assertEquals(1, store.retract("q", 0, 5));
        assertEquals(1, store.currentTx());
    }

    @Test
    void emptyTransactionIsNotRecorded() {
        store.assertValue("p", 0, 10, "A");
        assertEquals(1, store.transact(tx -> { }));
        assertEquals(1, store.currentTx());
    }

    @Test
    void transactionWhoseOperationsCancelOutIsNotRecorded() {
        store.assertValue("p", 0, 10, "A");
        long tx = store.transact(t -> {
            t.assertValue("p", 3, 6, "B");
            t.assertValue("p", 3, 6, "A");
        });
        assertEquals(1, tx);
        assertEquals(1, store.currentTx());
        assertEquals(List.of(seg(0, 10, "A")), store.history("p"));
    }

    @Test
    void multiKeyTransactionGetsOneTxIdAndLaterOpsSeeEarlierOnes() {
        long tx = store.transact(t -> {
            t.assertValue("a", 0, 5, "1");
            t.assertValue("b", 0, 5, "2");
            t.retract("a", 0, 2);
        });
        assertEquals(1, tx);
        assertEquals(List.of(seg(2, 5, "1")), store.history("a", 1));
        assertEquals(Map.of("a", "1", "b", "2"), store.snapshot(3, 1));
        assertEquals(Map.of("b", "2"), store.snapshot(0, 1));
    }

    @Test
    void failingTransactionCommitsNothing() {
        store.assertValue("p", 0, 10, "A");
        assertThrows(IllegalStateException.class, () -> store.transact(t -> {
            t.assertValue("p", 0, 10, "Z");
            t.assertValue("q", 0, 10, "Y");
            throw new IllegalStateException("boom");
        }));
        assertEquals(1, store.currentTx());
        assertEquals(List.of(seg(0, 10, "A")), store.history("p"));
        assertTrue(store.history("q").isEmpty());
    }

    @Test
    void invalidOperationInsideTransactionCommitsNothing() {
        assertThrows(IllegalArgumentException.class, () -> store.transact(t -> {
            t.assertValue("p", 0, 10, "A");
            t.retract("p", 7, 7);
        }));
        assertEquals(0, store.currentTx());
        assertTrue(store.history("p").isEmpty());
    }

    @Test
    void txHandleIsDeadAfterTransactionReturns() {
        @SuppressWarnings("unchecked")
        Tx<String, String>[] leaked = new Tx[1];
        store.transact(t -> {
            leaked[0] = t;
            t.assertValue("p", 0, 1, "A");
        });
        assertThrows(IllegalStateException.class, () -> leaked[0].assertValue("p", 5, 6, "B"));
        assertThrows(IllegalStateException.class, () -> leaked[0].retract("p", 0, 1));
        assertEquals(List.of(seg(0, 1, "A")), store.history("p"));
    }

    @Test
    void backwardsClockIsRejectedAndNothingIsRecorded() {
        store.assertValue("p", 0, 10, "A");
        now = 90;
        assertThrows(IllegalStateException.class, () -> store.assertValue("p", 0, 10, "B"));
        assertEquals(1, store.currentTx());
        assertEquals(List.of(seg(0, 10, "A")), store.history("p"));
        now = 100;
        assertEquals(2, store.assertValue("p", 0, 10, "B"));
    }

    @Test
    void txAtTimeFindsLatestTxNotAfterTimestamp() {
        now = 100;
        store.assertValue("p", 0, 1, "A");
        now = 100;
        store.assertValue("p", 1, 2, "A");
        now = 150;
        store.assertValue("p", 2, 3, "A");
        assertEquals(0, store.txAtTime(99));
        assertEquals(2, store.txAtTime(100));
        assertEquals(2, store.txAtTime(149));
        assertEquals(3, store.txAtTime(150));
        assertEquals(3, store.txAtTime(Long.MAX_VALUE));
        assertEquals(0, new BitemporalStore<String, String>(() -> 0).txAtTime(5));
    }

    @Test
    void snapshotIsSortedByKey() {
        store.assertValue("b", 0, 10, "2");
        store.assertValue("c", 0, 10, "3");
        store.assertValue("a", 5, 10, "1");
        assertEquals(List.of("b", "c"), List.copyOf(store.snapshot(1, 3).keySet()));
        assertEquals(List.of("a", "b", "c"), List.copyOf(store.snapshot(7, 3).keySet()));
        assertEquals(List.of("b", "c"), List.copyOf(store.snapshot(7, 2).keySet()));
        assertEquals(List.of(), List.copyOf(store.snapshot(10, 3).keySet()));
    }

    @Test
    void diffListsOnlyDifferingPieces() {
        store.assertValue("p", 0, 10, "A");
        store.assertValue("p", 3, 6, "B");
        store.retract("p", 8, 10);
        assertEquals(List.of(new Delta<>(3, 6, "A", "B"), new Delta<>(8, 10, "A", null)),
                store.diff("p", 1, 3));
        assertEquals(List.of(new Delta<>(3, 6, "B", "A"), new Delta<>(8, 10, null, "A")),
                store.diff("p", 3, 1));
        assertEquals(List.of(new Delta<>(8, 10, "A", null)), store.diff("p", 2, 3));
        assertTrue(store.diff("p", 2, 2).isEmpty());
        assertEquals(List.of(new Delta<>(0, 10, null, "A")), store.diff("p", 0, 1));
    }

    @Test
    void diffCoalescesAdjacentPiecesWithTheSameChange() {
        store.assertValue("p", 0, 10, "A");
        store.transact(t -> {
            t.assertValue("p", 0, 4, "B");
            t.assertValue("p", 4, 8, "B");
        });
        assertEquals(List.of(new Delta<>(0, 8, "A", "B")), store.diff("p", 1, 2));
    }

    @Test
    void diffKeepsAdjacentPiecesWithDifferentChangesApart() {
        store.assertValue("p", 0, 10, "A");
        store.transact(t -> {
            t.assertValue("p", 0, 4, "B");
            t.assertValue("p", 4, 8, "C");
        });
        assertEquals(List.of(new Delta<>(0, 4, "A", "B"), new Delta<>(4, 8, "A", "C")),
                store.diff("p", 1, 2));
    }

    @Test
    void revisionsTrackChangingBeliefAboutOneInstant() {
        now = 10;
        store.assertValue("p", 0, 10, "100");      // tx1: 5 -> 100
        now = 20;
        store.assertValue("p", 0, 3, "90");        // tx2: does not touch 5
        now = 30;
        store.assertValue("p", 4, 6, "120");       // tx3: 5 -> 120
        now = 40;
        store.assertValue("p", 0, 10, "120");      // tx4: 5 stays 120
        now = 50;
        store.retract("p", 5, 6);                  // tx5: 5 -> unknown
        now = 60;
        store.assertValue("p", 5, 6, "130");       // tx6: 5 -> 130
        assertEquals(List.of(new Revision<>(1, 10, "100"), new Revision<>(3, 30, "120"),
                new Revision<>(5, 50, null), new Revision<>(6, 60, "130")), store.revisions("p", 5));
    }

    @Test
    void revisionsOfNeverValuedInstantAreEmpty() {
        store.assertValue("p", 0, 10, "A");
        assertTrue(store.revisions("p", 20).isEmpty());
        assertTrue(store.revisions("zzz", 5).isEmpty());
    }

    @Test
    void revisionsStartAtFirstTxThatGaveTheInstantAValue() {
        store.assertValue("p", 0, 5, "A");
        store.assertValue("p", 5, 10, "B");
        assertEquals(List.of(new Revision<>(2, 100, "B")), store.revisions("p", 7));
    }

    @Test
    void argumentsAreValidated() {
        store.assertValue("p", 0, 10, "A");
        assertThrows(IllegalArgumentException.class, () -> store.valueAt("p", 1, -1));
        assertThrows(IllegalArgumentException.class, () -> store.valueAt("p", 1, 2));
        assertThrows(IllegalArgumentException.class, () -> store.history("p", 2));
        assertThrows(IllegalArgumentException.class, () -> store.snapshot(1, 5));
        assertThrows(IllegalArgumentException.class, () -> store.diff("p", 0, 9));
        assertThrows(IllegalArgumentException.class, () -> store.assertValue(null, 0, 1, "A"));
        assertThrows(IllegalArgumentException.class, () -> store.assertValue("p", 0, 1, null));
        assertThrows(IllegalArgumentException.class, () -> store.assertValue("p", 4, 4, "A"));
        assertThrows(IllegalArgumentException.class, () -> store.retract("p", 4, 3));
        assertThrows(IllegalArgumentException.class, () -> store.retract(null, 0, 1));
        assertThrows(IllegalArgumentException.class, () -> store.transact(null));
        assertEquals(1, store.currentTx());
    }

    @Test
    void historyListsAreUnmodifiable() {
        store.assertValue("p", 0, 10, "A");
        assertThrows(UnsupportedOperationException.class, () -> store.history("p").clear());
        assertThrows(UnsupportedOperationException.class, () -> store.snapshot(1, 1).clear());
    }
}
